UPDATE message 
SET is_read = 1
WHERE conversation_id = #{conversationId}
AND receiver_id = #{userId}
AND is_read = 0

UPDATE message 
SET is_read = 1
WHERE message_id = #{messageId}
AND receiver_id = #{userId}
AND is_read = 0

UPDATE message 
SET is_read = 1
WHERE receiver_id = #{userId} 
AND sender_id = #{senderId}
AND is_read = 0
AND message_type != 3

mapper.select:
SELECT COUNT(*) 
FROM message 
WHERE receiver_id = #{userId} 
AND sender_id = #{senderId}
AND is_read = 0
AND message_type != 3

SELECT MIN(m.message_id) as messageId, MIN(m.conversation_id) as conversationId, m.sender_id as senderId, '系统' as senderName, null as senderAvatar, COUNT(DISTINCT m.receiver_id) as receiverId, GROUP_CONCAT(DISTINCT u.username ORDER BY u.username SEPARATOR ', ') as receiverName, m.content, m.content_type as contentType, m.message_type as messageType, SUM(CASE WHEN m.is_read = 1 THEN 1 ELSE 0 END) as isRead, MAX(m.created_at) as createdAt, m.image_url as imageUrl, true as isSystem FROM message m LEFT JOIN user u ON m.receiver_id = u.user_id WHERE m.sender_id = 0
AND m.content_type = #{contentType}
GROUP BY m.content, m.content_type, m.message_type, m.image_url, m.sender_id ORDER BY MAX(m.created_at) DESC
